// Generated bytes and temporary profiles only; never access saved wallet evidence.
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import { mkdtemp, mkdir, writeFile, readFile, rm, stat, readdir, symlink, link } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { gzipSync } from 'node:zlib';
import { EvidenceArchive, ARCHIVE_NAME, REFERENCE, REFERENCE_PREFIX } from './evidence-archive.mjs';
import { readEvidenceFile, writeEvidenceJson, compactEvidenceFile, expandEvidenceFile } from './evidence-storage.mjs';

const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const integrityError = error => {
  assert.equal(error.code, 'GODL_EVIDENCE_INTEGRITY');
  return true;
};
const exactBytes = () => Buffer.from(' \r\n{ "unsafe":9007199254740993123456789, "raw" : "\\u007b\\\"n\\\":9007199254740993,\\\"s\\\":\\\"a\\\\b\\\\n\\\"\\u007d", "tail": -9007199254740993123456789 }\t\n');

async function fixture(t) {
  const base = await mkdtemp(join(tmpdir(), 'godl-evidence-archive-'));
  const root = join(base, 'profile'), run = join(root, 'run');
  await mkdir(run, { recursive: true, mode: 0o700 });
  await mkdir(join(root, 'finalized-cache'), { mode: 0o700 });
  const archives = [];
  t.after(async () => {
    for (const archive of archives.reverse()) {
      try { archive.close(); } catch { /* already closed for restart/corruption proof */ }
    }
    await rm(base, { recursive: true, force: true });
  });
  return {
    base, root, run,
    path: join(run, 'response-000001.json'),
    next: number => join(run, `response-${String(number).padStart(6, '0')}.json`),
    cache: join(root, 'finalized-cache', `${'a'.repeat(64)}.json`),
    archive(options) { const archive = new EvidenceArchive(root, options); archives.push(archive); return archive; },
  };
}

function counts(archive) {
  return Object.fromEntries(['objects', 'records', 'paths'].map(table =>
    [table, archive.db.prepare(`SELECT count(*) AS n FROM ${table}`).get().n]));
}

function sameBucketPath(f) {
  const bucket = hash(Buffer.from('run/response-000001.json')).slice(0, 2);
  for (let number = 2; number < 100000; number++) {
    const name = `response-${String(number).padStart(6, '0')}.json`;
    if (hash(Buffer.from(`run/${name}`)).slice(0, 2) === bucket) return join(f.run, name);
  }
  throw new Error('Unable to generate a synthetic marker bucket collision');
}

test('archive restores exact unsafe numeric digits, raw escapes and surrounding bytes after reopening', async t => {
  const f = await fixture(t), bytes = exactBytes(), archive = f.archive();
  const digest = archive.put(f.path, bytes);
  assert.equal(digest, hash(bytes));
  assert.equal(archive.has(f.path), true);
  assert.deepEqual(archive.read(f.path), bytes);
  assert.deepEqual(archive.readHash(digest), bytes);
  archive.close();
  const reopened = f.archive({ readOnly: true });
  assert.deepEqual(reopened.read(f.path), bytes);
  assert.deepEqual(reopened.readHash(digest), bytes);
  assert.equal((await stat(join(f.root, ARCHIVE_NAME))).mode & 0o777, 0o600);
});

test('raw tokens deduplicate across envelopes and identical records reuse objects and records', async t => {
  const f = await fixture(t), archive = f.archive();
  const raw = '"same\\u0020synthetic\\nbody"';
  const first = Buffer.from(` {"raw":${raw},"unsafe":9007199254740993}\n`);
  const second = Buffer.from(`\t{"unsafe":9007199254740995,"raw":${raw} }\r\n`);
  archive.put(f.path, first); archive.put(f.next(2), second); archive.put(f.cache, first);
  archive.put(f.path, first);
  assert.deepEqual(counts(archive), { objects: 1, records: 2, paths: 3 });
  assert.deepEqual(archive.read(f.path), first);
  assert.deepEqual(archive.read(f.next(2)), second);
  assert.deepEqual(archive.read(f.cache), first);
});

test('whole-byte fallback preserves invalid UTF-8, non-JSON and JSON without a top-level raw string', async t => {
  const f = await fixture(t), archive = f.archive();
  const cases = [Buffer.from([0xff, 0xfe, 0x00, 0xc3, 0x28]), Buffer.from('not JSON\r\n'), Buffer.alloc(0),
    Buffer.from('{"nested":{"raw":"inner"},"unsafe":9007199254740993}'), Buffer.from('{"raw":{"value":1}}')];
  for (const [index, bytes] of cases.entries()) {
    const digest = archive.put(f.next(index + 1), bytes);
    assert.deepEqual(archive.readHash(digest), bytes);
    const record = archive.db.prepare('SELECT object_hash,envelope_length,split_at FROM records WHERE hash=?').get(digest);
    assert.equal(record.object_hash, hash(bytes));
    assert.equal(record.envelope_length, 0);
    assert.equal(record.split_at, 0);
  }
  assert.deepEqual(counts(archive), { objects: cases.length, records: cases.length, paths: cases.length });
});

test('immutable path conflicts preserve original records and roll back unused objects', async t => {
  const f = await fixture(t), archive = f.archive(), original = exactBytes();
  archive.put(f.path, original);
  assert.throws(() => archive.put(f.path, Buffer.from('{"raw":"conflict"}')), integrityError);
  assert.deepEqual(archive.read(f.path), original);
  assert.deepEqual(counts(archive), { objects: 1, records: 1, paths: 1 });
  assert.throws(() => archive.put(f.next(2), 'not a Buffer'), integrityError);
  assert.equal(archive.has(f.next(2)), false);
});

test('read-only archives allow reads but reject insertion and never create a missing archive', async t => {
  const f = await fixture(t), archive = f.archive(), bytes = exactBytes();
  archive.put(f.path, bytes); archive.close();
  const reader = f.archive({ readOnly: true });
  assert.deepEqual(reader.read(f.path), bytes);
  assert.throws(() => reader.put(f.next(2), bytes), integrityError);
  const otherRoot = join(f.base, 'missing-profile'); await mkdir(otherRoot);
  assert.throws(() => new EvidenceArchive(otherRoot, { readOnly: true }));
  assert.deepEqual(await readdir(otherRoot), []);
});

test('unknown archive versions and unexpected schemas fail closed without replacing the database', async t => {
  const f = await fixture(t), archive = f.archive();
  archive.put(f.path, exactBytes()); archive.db.exec('PRAGMA user_version=999'); archive.close();
  const original = await readFile(join(f.root, ARCHIVE_NAME));
  for (const readOnly of [false, true]) {
    assert.throws(() => f.archive({ readOnly }), integrityError);
    assert.deepEqual(await readFile(join(f.root, ARCHIVE_NAME)), original);
  }
  const db = new DatabaseSync(join(f.root, ARCHIVE_NAME));
  db.exec('PRAGMA user_version=1; CREATE TABLE unexpected(value TEXT)'); db.close();
  assert.throws(() => f.archive(), integrityError);
});

test('profile mismatch, unsupported logical paths and symlinked profile/run/database paths are rejected', async t => {
  const f = await fixture(t), archive = f.archive(), bytes = exactBytes();
  const other = join(f.base, 'other'); await mkdir(join(other, 'run'), { recursive: true });
  for (const path of [join(other, 'run', 'response-000001.json'), join(f.run, 'settings.json'),
    join(f.root, 'finalized-cache', 'not-a-digest.json'), join(f.run, 'response-1.json')]) {
    assert.throws(() => archive.put(path, bytes), integrityError);
  }
  const linkedRun = join(f.root, 'linked-run'); await symlink(f.run, linkedRun);
  assert.throws(() => archive.put(join(linkedRun, 'response-000001.json'), bytes), integrityError);
  const linkedRoot = join(f.base, 'linked-profile'); await symlink(f.root, linkedRoot);
  assert.throws(() => new EvidenceArchive(linkedRoot), integrityError);
  archive.close();
  const database = join(f.root, ARCHIVE_NAME), moved = join(f.base, 'database');
  await writeFile(moved, await readFile(database)); await rm(database); await symlink(moved, database);
  assert.throws(() => f.archive(), integrityError);
});

test('hard-linked database is rejected instead of sharing evidence between profiles', async t => {
  const f = await fixture(t), archive = f.archive(); archive.put(f.path, exactBytes()); archive.close();
  await link(join(f.root, ARCHIVE_NAME), join(f.base, 'shared-database'));
  assert.throws(() => f.archive(), integrityError);
});

test('archive reads enforce byte bounds and missing records remain integrity errors', async t => {
  const f = await fixture(t), archive = f.archive(), bytes = exactBytes(), digest = archive.put(f.path, bytes);
  assert.deepEqual(archive.read(f.path, bytes.length), bytes);
  for (const maximum of [bytes.length - 1, 0, -1, 1.5, NaN, Infinity, 128 * 1024 * 1024 + 1]) {
    assert.throws(() => archive.readHash(digest, maximum), integrityError);
  }
  assert.throws(() => archive.read(f.next(2)), integrityError);
  for (const missing of ['b'.repeat(64), '../escape', 'A'.repeat(64)]) {
    assert.throws(() => archive.readHash(missing), integrityError);
  }
});

test('corrupt payload, record envelope, lengths and missing objects fail integrity validation', async t => {
  const mutations = [
    'UPDATE objects SET payload=x\'00\'',
    'UPDATE objects SET original_length=original_length+1',
    'UPDATE records SET envelope=x\'00\'',
    'UPDATE records SET original_length=original_length-1',
    'UPDATE records SET split_at=envelope_length+1',
    'UPDATE records SET object_hash=\'' + 'b'.repeat(64) + '\'',
    'DELETE FROM objects',
  ];
  for (const sql of mutations) await t.test(sql, async child => {
    const f = await fixture(child), archive = f.archive(), digest = archive.put(f.path, exactBytes());
    archive.db.exec('PRAGMA foreign_keys=OFF'); archive.db.exec(sql);
    assert.throws(() => archive.readHash(digest), integrityError);
  });
});

test('archive writes publish shared private markers that legacy JSON.parse cannot consume', async t => {
  const f = await fixture(t), archive = f.archive();
  const value = { raw: 'generated synthetic body', unsafe: '9007199254740993' };
  const expected = Buffer.from(JSON.stringify(value, null, 2) + '\n');
  const secondPath = sameBucketPath(f);
  for (const path of [f.path, secondPath, f.cache]) {
    assert.equal(await writeEvidenceJson(path, value, { archive }), path);
    assert.deepEqual(await readFile(path), REFERENCE);
    assert.throws(() => JSON.parse(REFERENCE.toString('utf8')), SyntaxError);
    assert.deepEqual(await readEvidenceFile(path, { archive }), expected);
    assert.deepEqual(await readEvidenceFile(path), expected);
    assert.equal((await stat(path)).mode & 0o777, 0o600);
  }
  const first = await stat(f.path), second = await stat(secondPath);
  assert.equal(first.ino, second.ino); assert.equal(first.dev, second.dev);
  assert.ok(first.nlink >= 3);
  assert.equal((await stat(join(f.root, '.evidence-reference-markers'))).mode & 0o777, 0o700);
  assert.deepEqual(counts(archive), { objects: 1, records: 1, paths: 3 });
  assert.equal((await readdir(f.run)).length, 2);
});

test('marker links roll to a new private inode before exceeding the bounded link count', async t => {
  const f = await fixture(t), archive = f.archive(), value = { raw: 'generated rollover body' };
  await writeEvidenceJson(f.path, value, { archive });
  const original = await stat(f.path);
  // Seed links directly to exercise the boundary without 1024 durable SQLite writes.
  for (let number = original.nlink; number < 1024; number++) {
    await link(f.path, join(f.base, `synthetic-link-${number}`));
  }
  assert.equal((await stat(f.path)).nlink, 1024);
  const secondPath = sameBucketPath(f);
  await writeEvidenceJson(secondPath, value, { archive });
  const second = await stat(secondPath);
  assert.notEqual(second.ino, original.ino);
  assert.equal((await stat(f.path)).nlink, 1024);
  assert.ok(second.nlink <= 1024);
  assert.equal(second.mode & 0o777, 0o600);
  assert.deepEqual(await readFile(secondPath), REFERENCE);
  assert.deepEqual(await readEvidenceFile(f.path), await readEvidenceFile(secondPath));
});

test('archived writer reuses matching evidence and preserves conflicting bytes', async t => {
  const f = await fixture(t), archive = f.archive(), value = { raw: 'generated body' };
  await writeEvidenceJson(f.path, value, { archive });
  const before = await readFile(f.path), info = await stat(f.path);
  assert.equal(await writeEvidenceJson(f.path, value, { archive }), f.path);
  await assert.rejects(writeEvidenceJson(f.path, { raw: 'conflict' }, { archive }));
  assert.deepEqual(await readFile(f.path), before);
  assert.equal((await stat(f.path)).ino, info.ino);
  assert.deepEqual(await readEvidenceFile(f.path), Buffer.from(JSON.stringify(value, null, 2) + '\n'));
  assert.deepEqual(counts(archive), { objects: 1, records: 1, paths: 1 });
});

test('plain and gzip conversion restores original exact bytes and supports idempotent restart', async t => {
  const f = await fixture(t), archive = f.archive(), bytes = exactBytes();
  for (const [index, compressed] of [false, true].entries()) {
    const path = f.next(index + 1);
    await writeFile(compressed ? `${path}.gz` : path, compressed ? gzipSync(bytes) : bytes);
    assert.equal((await compactEvidenceFile(path, { archive })).status, 'compacted');
    assert.deepEqual(await readFile(path), REFERENCE);
    await assert.rejects(readFile(`${path}.gz`), { code: 'ENOENT' });
    assert.deepEqual(await readEvidenceFile(path), bytes);
    assert.equal((await compactEvidenceFile(path, { archive })).status, 'compacted');
    assert.equal((await expandEvidenceFile(path, { archive })).status, 'expanded');
    assert.deepEqual(await readFile(path), bytes);
    assert.equal((await stat(path)).mode & 0o777, 0o600);
    assert.equal((await expandEvidenceFile(path, { archive })).status, 'expanded');
  }
});

test('committed archive mappings can resume conversion after interruption before marker publication', async t => {
  const f = await fixture(t), bytes = exactBytes();
  let archive = f.archive();
  await writeFile(f.path, bytes); archive.put(f.path, bytes); archive.close();
  assert.deepEqual(await readFile(f.path), bytes);
  archive = f.archive();
  assert.equal((await compactEvidenceFile(f.path, { archive })).status, 'compacted');
  assert.deepEqual(await readFile(f.path), REFERENCE);
  assert.deepEqual(await readEvidenceFile(f.path), bytes);
  assert.deepEqual(counts(archive), { objects: 1, records: 1, paths: 1 });
});

test('committed mappings remain readable before a marker exists and corrupt mappings cannot become cache misses', async t => {
  const f = await fixture(t), archive = f.archive(), bytes = exactBytes();
  archive.put(f.cache, bytes);
  assert.deepEqual(await readEvidenceFile(f.cache), bytes);
  assert.deepEqual(await readEvidenceFile(f.cache, { archive }), bytes);
  archive.db.exec('PRAGMA foreign_keys=OFF; DELETE FROM objects');
  await assert.rejects(readEvidenceFile(f.cache), integrityError);
  await assert.rejects(readEvidenceFile(f.cache, { archive }), integrityError);
});

test('conversion stage interruptions preserve readable evidence and restart safely', async t => {
  const f = await fixture(t), archive = f.archive(), bytes = exactBytes();
  for (const [index, stage] of ['archive-committed', 'reference-published'].entries()) {
    const path = f.next(index + 1); await writeFile(`${path}.gz`, gzipSync(bytes));
    const stages = [];
    await assert.rejects(compactEvidenceFile(path, { archive, onStage(value) {
      stages.push(value); if (value === stage) throw new Error('synthetic interruption');
    } }), /synthetic interruption/);
    assert.ok(stages.includes(stage));
    assert.deepEqual(await readEvidenceFile(path), bytes);
    assert.equal((await compactEvidenceFile(path, { archive })).status, 'compacted');
    assert.deepEqual(await readFile(path), REFERENCE);
    await assert.rejects(readFile(`${path}.gz`), { code: 'ENOENT' });
  }
});

test('conversion and expansion preserve conflicting legacy forms instead of hiding either original', async t => {
  const f = await fixture(t), archive = f.archive(), bytes = exactBytes();
  await writeFile(f.path, bytes); const conflict = gzipSync('generated conflicting body');
  await writeFile(`${f.path}.gz`, conflict);
  await assert.rejects(compactEvidenceFile(f.path, { archive }));
  assert.deepEqual(await readFile(f.path), bytes);
  assert.deepEqual(await readFile(`${f.path}.gz`), conflict);
  await rm(`${f.path}.gz`);
  await compactEvidenceFile(f.path, { archive });
  await writeFile(`${f.path}.gz`, conflict);
  await assert.rejects(expandEvidenceFile(f.path, { archive }));
  assert.deepEqual(await readFile(f.path), REFERENCE);
  assert.deepEqual(await readFile(`${f.path}.gz`), conflict);
  assert.deepEqual(archive.read(f.path), bytes);
});

test('marker reads reject unknown versions, wrong profiles, bounds and missing mappings with integrity errors', async t => {
  const f = await fixture(t), archive = f.archive(), bytes = exactBytes();
  archive.put(f.path, bytes); await writeFile(f.path, REFERENCE);
  await assert.rejects(readEvidenceFile(f.path, { maxBytes: bytes.length - 1 }), integrityError);
  await writeFile(f.next(2), REFERENCE);
  await writeFile(`${f.next(2)}.gz`, gzipSync('must not refetch or use fallback'));
  await assert.rejects(readEvidenceFile(f.next(2)), integrityError);
  await writeFile(f.next(3), Buffer.concat([REFERENCE_PREFIX, Buffer.from('999\n')]));
  await assert.rejects(readEvidenceFile(f.next(3)), integrityError);
  const otherRoot = join(f.base, 'other-profile'); await mkdir(join(otherRoot, 'run'), { recursive: true });
  const other = new EvidenceArchive(otherRoot); t.after(() => other.close());
  await assert.rejects(readEvidenceFile(f.path, { archive: other }), integrityError);
});

test('markers with missing or corrupt databases fail integrity instead of ENOENT or gzip fallback', async t => {
  const f = await fixture(t);
  await writeFile(f.path, REFERENCE); await writeFile(`${f.path}.gz`, gzipSync('fallback must stay hidden'));
  await assert.rejects(readEvidenceFile(f.path), integrityError);
  assert.deepEqual(await readdir(f.root), ['finalized-cache', 'run']);
  await writeFile(join(f.root, ARCHIVE_NAME), 'synthetic corrupt database');
  await assert.rejects(readEvidenceFile(f.path), integrityError);
  assert.equal(await readFile(join(f.root, ARCHIVE_NAME), 'utf8'), 'synthetic corrupt database');
});

test('marker reads reject corrupt archived objects and closed supplied database handles', async t => {
  const f = await fixture(t), archive = f.archive();
  archive.put(f.path, exactBytes()); await writeFile(f.path, REFERENCE);
  archive.db.exec('UPDATE objects SET payload=x\'00\'');
  await assert.rejects(readEvidenceFile(f.path), integrityError);
  archive.close();
  await assert.rejects(readEvidenceFile(f.path, { archive }), integrityError);
});

test('oversized new records keep their portable original bytes and offline expansion skips them safely', async t => {
  const f = await fixture(t);
  const archive = f.archive();
  const value = { raw: 'x'.repeat(64 * 1024 * 1024) };
  const expected = Buffer.from(JSON.stringify(value, null, 2) + '\n');
  await writeEvidenceJson(f.path, value, { archive });
  assert.deepEqual(await readFile(f.path), expected);
  assert.equal(archive.has(f.path), false);
  assert.deepEqual(await expandEvidenceFile(f.path, { archive }), { status: 'skipped', reason: 'oversized', path: f.path });
  assert.deepEqual(await readEvidenceFile(f.path, { archive }), expected);
});

test('same-value writer retry heals a missing marker after the archive transaction committed', async t => {
  const f = await fixture(t), archive = f.archive(), value = { raw: 'synthetic retry' };
  const bytes = Buffer.from(JSON.stringify(value, null, 2) + '\n');
  archive.put(f.path, bytes);
  await writeEvidenceJson(f.path, value, { archive });
  assert.deepEqual(await readFile(f.path), REFERENCE);
  assert.deepEqual(await readEvidenceFile(f.path, { archive }), bytes);
});
